import{_ as e,o as n,c as t,a5 as i}from"./chunks/framework.CsGesDJn.js";const d=JSON.parse('{"title":"Kế hoạch E50-09 / DA-950","description":"","frontmatter":{},"headers":[],"relativePath":"feature/media-package-campaign/campaign-collaborators/plan.md","filePath":"feature/media-package-campaign/campaign-collaborators/plan.md"}'),o={name:"feature/media-package-campaign/campaign-collaborators/plan.md"};function r(c,a,l,h,s,p){return n(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="ke-hoach-e50-09-da-950" tabindex="-1">Kế hoạch E50-09 / DA-950 <a class="header-anchor" href="#ke-hoach-e50-09-da-950" aria-label="Permalink to &quot;Kế hoạch E50-09 / DA-950&quot;">​</a></h1><h2 id="hien-trang" tabindex="-1">Hiện trạng <a class="header-anchor" href="#hien-trang" aria-label="Permalink to &quot;Hiện trạng&quot;">​</a></h2><p>Entity, enum, FK và unique pair đã có trong init PostgreSQL V2. Repository chưa có truy vấn nghiệp vụ; CollaboratorServiceImpl đang stub. Gateway đã forward /api/v1/** sang Business Service. Campaign page không dành cho Creator, nên thêm trang theo dõi đối tác riêng để không mở quyền sửa/approve kế hoạch cho Creator.</p><h2 id="backend" tabindex="-1">Backend <a class="header-anchor" href="#backend" aria-label="Permalink to &quot;Backend&quot;">​</a></h2><ul><li>CampaignCollaboratorAccess: kiểm tra Workspace/Agency active, membership thực trong DB (kể cả ClientProfile), Owner fallback. Không tin role/scope trong JWT.</li><li>CampaignCollaboratorService: context Campaign hiện tại, danh bạ theo Agency, danh sách liên kết phân trang; join projection tránh N+1 và không lộ contact nội bộ của danh bạ cho Client.</li><li>Gán: khóa hàng Campaign, validate cùng Agency, trả lại liên kết đã tồn tại; UNIQUE trong DB là lớp bảo vệ cuối. Cập nhật: khóa link, kiểm tra scope và expectedUpdatedAt, ghi timestamp microsecond phù hợp PostgreSQL.</li><li>GET /workspaces/{id}/campaign-collaborators?page=0&amp;size=20 trả context + page.</li><li>GET /workspaces/{id}/collaborators?page=0&amp;size=20 dành cho người có quyền ghi.</li><li>POST /workspaces/{id}/campaigns/{campaignId}/collaborators: {collaboratorId}.</li><li>PUT /workspaces/{id}/campaigns/{campaignId}/collaborators/{linkId}: {cooperationStatus, expectedUpdatedAt}.</li><li>Legacy /collaborators/assign và /collaborators/campaign/{id}/cooperation delegate cùng service; legacy update không có token vẫn giữ last-write-wins.</li></ul><h2 id="frontend" tabindex="-1">Frontend <a class="header-anchor" href="#frontend" aria-label="Permalink to &quot;Frontend&quot;">​</a></h2><p>Route /workspaces/:id/campaign-partners, sidebar và access rule cho Owner/Manager/Creator/Client; giữ Package gate hiện có. Trang dùng quyền canEdit từ backend; Client chỉ thấy danh sách. Chọn đối tác phân trang; mỗi hàng có trạng thái đang lưu và thông tin cập nhật. Cung cấp liên kết từ Campaign page. Locale en/vi, responsive và semantic theme tokens.</p><h2 id="verification-va-rollout" tabindex="-1">Verification và rollout <a class="header-anchor" href="#verification-va-rollout" aria-label="Permalink to &quot;Verification và rollout&quot;">​</a></h2><p>Unit tests access/scoping/idempotence/reversible state/concurrency, controller validation, Playwright mock flow cho Manager/Creator/Client/empty/error. Chạy Maven, lint, type-check, build, browser tests. Không tự sửa dữ liệu thật. E50-08 CRUD vẫn là dependency để người dùng tự bổ sung danh bạ nếu đang rỗng.</p><h2 id="delta-da-949-950-—-thiet-ke-2026-10-13-chua-implementation" tabindex="-1">Delta DA-949/950 — thiết kế 2026-10-13, chưa implementation <a class="header-anchor" href="#delta-da-949-950-—-thiet-ke-2026-10-13-chua-implementation" aria-label="Permalink to &quot;Delta DA-949/950 — thiết kế 2026-10-13, chưa implementation&quot;">​</a></h2><p>Theo <a href="./../partner-directory/plan.html">partner-directory/plan.md</a>, picker chỉ active; assign mới phải lock/verify partner active và ghi first_used_at cùng transaction. Phối hợp lock ordering với delete/deactivate để không deadlock. Trả link đã tồn tại idempotently, kể cả partner inactive; giữ đọc/cập nhật hợp tác của link cũ. Legacy assign dùng cùng rule. Chỉ bổ sung parallel vi/en campaign.json cho badge inactive/lỗi unavailable và regression light/dark/mobile; không thay quyền DA-950.</p><p>OpenAPI đã đồng bộ tại <code>brandhub-business-service/docs/openapi.yaml</code> cho bốn endpoint mới. Opt-in <code>CampaignCollaboratorPostgresTest</code> chạy service với JPA thật trong transaction rollback-only, không khởi động seeders hoặc kết nối Mongo. HQL validation không có JDBC/DDL giúp kiểm tra projection/joins khi Docker tắt.</p>',12)])])}const m=e(o,[["render",r]]);export{d as __pageData,m as default};
